function validate([root]) {
  if (root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  let open = 1;
  for (const v of root) {
    if (open === 0) return 'Every value after the root needs a parent node.';
    open += v === null ? -1 : 1;
  }
  const values = root.filter(v => v !== null);
  if (values.length > 8500) return 'The tree has at most 8500 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > 25)) return 'Each node value is a whole number from 0 to 25.';
  return null;
}

