function smallestFromLeaf(root) {
  const path = [];
  let best = null;

  function dfs(node) {
    if (!node) {
      return;
    }
    path.push(String.fromCharCode(97 + node.val));
    if (!node.left && !node.right) {
      const candidate = path.slice().reverse().join('');
      if (best === null || candidate < best) {
        best = candidate;
      }
    }
    dfs(node.left);
    dfs(node.right);
    path.pop();
  }

  dfs(root);
  return best;
}

