function smallestFromLeaf(root) {
  // Breadth-first: carry each node's full string upward-read, collect the leaves' strings, sort them.
  const words = [];
  const queue = [[root, String.fromCharCode(97 + root.val)]];
  while (queue.length) {
    const [node, word] = queue.shift();
    if (!node.left && !node.right) words.push(word);
    for (const child of [node.left, node.right]) {
      if (child) queue.push([child, String.fromCharCode(97 + child.val) + word]);
    }
  }
  words.sort();
  return words[0];
}

